toolCalls.args:
{"command": "cd /tmp/sv-4afb0dd923d34cb1bede3abc2d3409c1

# Check if we have llvm-addr2line or addr2line for aarch64
which aarch64-linux-gnu-addr2line 2>/dev/null || which llvm-addr2line 2>/dev/null || which addr2line 2>/dev/null || echo "need to install"", "description": "Check for addr2line tool"}

arguments.command:
cd /tmp/sv-4afb0dd923d34cb1bede3abc2d3409c1
# Check sections in the actual binary
aarch64-linux-gnu-readelf -S sym_download | grep -E 'text|data|rodata|\.bss' | head -10
echo "---"
# Look for dynamic symbols near those addresses
aarch64-linux-gnu-readelf -sW sym_download | awk '{
  if (NR <= 3) next;
  addr = strtonum("0x"$2);
  size = strtonum($3);
  if (addr > 0 && size > 0 && addr <= 0x2f4b20 && addr + size > 0x2f4b20) print "0x2f4b20 => "$0;
  if (addr > 0 && size > 0 && addr <= 0x2f4c84 && addr + size > 0x2f4c84) print "0x2f4c84 => "$0;
}'

